+  }
+  for (const forbidden of ['REPLACE_' + 'AFTER_AUDIT', 'TODO_' + 'OWNER', 'TBD_' + 'OWNER']) {
+    if (content.includes(forbidden))
+      errors.push(path.basename(filePath) + ' contains forbidden placeholder ' + forbidden);
+  }
+  return errors;
+}
